import React, { Component } from "react";
import { FormattedMessage } from "react-intl";
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
import Loader from "react-loader-spinner";
import Pagination2 from "react-js-pagination";

// Redux
import { connect } from "react-redux";
import { bindActionCreators } from "redux";
import Widget04 from "../../../../Utils/Widgets04";
import { handleExceptionMannually } from "../../../../actions/utils";
import { fetchVisaIssuerTransactions, downloadVisaIssuerCsv } from "../../../../actions/filesets";

// components
import { Card, CardBody, CardHeader, Col, Row, Table as Table2, CardGroup, Button, Input } from "reactstrap";
import PostingTable from "../../../../components/PostingTable";
import PostingTableHeader from "../../../../components/PostingTableHeader";
import ManuallResolutionModal from "../../../../components/Modal";

class VisaIssuerTransactions extends Component {
	constructor (props) {
		super(props);
		this.state = {
			modal            : false,
			activePage       : 1,
			manualResolution : false,
			selectedItem     : {},
		};
	}

	static getDerivedStateFromProps (props, state) {
		if (props.manualResolution !== state.manualResolution) {
			return {
				manualResolution : props.manualResolution,
				selectedItem     : props.selectedItem,
			};
		}

		if (props.match.params.page !== state.activePage) {
			return {
				activePage : parseInt(props.match.params.page),
			};
		}

		// Return null if the state hasn't changed
		return null;
	}

	componentDidMount () {
		this.props.fetchVisaIssuerTransactions(
			this.props.match.params.date,
			this.props.match.params.searchBy,
			this.props.match.params.page - 1,
		);
	}

	componentDidUpdate (prevProps) {
		if (this.props.selectedAffiliateCode !== prevProps.selectedAffiliateCode) {
			this.props.fetchVisaIssuerTransactions(
				this.props.match.params.date,
				this.props.match.params.searchBy,
				this.props.match.params.page - 1,
			);
		}

		if (this.props.match.params.page !== prevProps.match.params.page) {
			this.props.fetchVisaIssuerTransactions(
				this.props.match.params.date,
				this.props.match.params.searchBy,
				this.props.match.params.page - 1,
			);
		}

		if (this.props.match.params.searchBy !== prevProps.match.params.searchBy) {
			this.props.fetchVisaIssuerTransactions(
				this.props.match.params.date,
				this.props.match.params.searchBy,
				this.props.match.params.page - 1,
			);
		}

		if (this.props.match.params.date !== prevProps.match.params.date) {
			this.props.fetchVisaIssuerTransactions(
				this.props.match.params.date,
				this.props.match.params.searchBy,
				this.props.match.params.page - 1,
			);
		}
	}

	handlePageChange = (pageNumber) => {
		this.props.history.push(
			`/visa/settlement/issuer/${this.props.match.params.date}/transactions/${this.props.match.params
				.searchBy}/${pageNumber}`,
		);
		this.setState({ activePage: pageNumber });
	};

	createSelectItems = (selectOptions) => {
		let items = [];
		for (let i = 0; i < selectOptions.length; i++) {
			items.push(<option key={i}>{selectOptions[i]}</option>);
		}
		return items;
	};

	handleSelect = (event) => {
		this.props.history.push(
			`/visa/settlement/issuer/${this.props.match.params.date}/transactions/${event.target.value}/${this.props
				.match.params.page}`,
		);
		this.setState({
			searchBy : event.target.value,
		});
	};

	render () {
		const VisaIssuerTransactionHeader = [
			"Action",
			"Bin",
			"Reconciliation Code",
			"Reconciliation Purpose",
			"Pan",
			"Acquirer Reference Number",
			"Transaction Date",
			"Settlement Amount",
			"Settlement Currency Code",
			"Transaction Amount",
			"Transaction Currency Code",
			"Card Acceptor Name",
			"Card Acceptor Location",
			"Acquirer Country Code",
			"Auth Id",
			"Bin Id",
			"Affiliate Code",
			"Card Id",
			"Card Name",
			"Card Type",
			"Masked Pan",
			"CrDr",
			"Posting Settlement Amount",
			"Narration",
			"Txn Date",
			"Txn Date Local",
			"Txn Code",
			"Branch",
			"Ccy",
			"Mid",
			"Lcy Amount",
			"Product",
			"Sub Group",
			"Postilion Rrn",
			"FlexCube Lcy Amt",
			"Postilion Rrn Resolver",
			"FlexCube Lcy Amt Resolver",
			"Postilion Rrn Resolved Date",
			"flexCube Lcy Amt Resolved Date",
			"Batch Date",
			"X Rate",
		];
		if (this.props.visaIssuerTransactions) {
			if (this.props.visaIssuerTransactions.data.content) {
				if (this.props.visaIssuerTransactions.data.content.length > 0) {
					delete this.props.visaIssuerTransactions.data.content[0].inctf01;
					// delete this.props.fileSets.visaIssuerTransactions.data.content[0].id;
					var columnHeaders = this.props.visaIssuerTransactions.data.content[0];
					var newRows = [ { name: "Action", title: "Action" } ];
					for (var name in columnHeaders) {
						var newObj = {};
						newObj.name = name;
						newObj.title = name;
						newRows.push(newObj);
					}
					var payloadArray = [];
					this.props.visaIssuerTransactions.data.content.forEach(function (item) {
						if (item.interAffIssuer) {
							delete item.interAffIssuer;
						}
						// delete item.id
						payloadArray.push(item);
					});
				}
			}
		}

		// const { defaultHiddenColumnNames } = this.state;
		return (
			<div className='animated fadeIn'>
				<Row>
					<Col>
						{this.props.visaIssuerTransactions ? (
							<CardGroup className='mb-4'>
								<Widget04
									icon='icon-people'
									color='info'
									header={this.props.visaIssuerTransactions.data.totalElements.toLocaleString()}
									value='25'
								>
									Transactions
								</Widget04>
								<Widget04 icon='icon-user-follow' color='success' header='0' value='25'>
									Successful Transactions
								</Widget04>
								<Widget04 icon='icon-basket-loaded' color='warning' header='0' value='25'>
									Credits
								</Widget04>
								<Widget04 icon='icon-pie-chart' color='primary' header='0' value='5'>
									Debits
								</Widget04>
								<Widget04 icon='icon-speedometer' color='danger' header='0' value='25'>
									Amount
								</Widget04>
							</CardGroup>
						) : null}
					</Col>
				</Row>
				<Row>
					<Col lg={12}>
						<Card>
							{/* Manual resolution modal */}
							<ManuallResolutionModal
								updateTransactionType={"issuer"}
								openModal={this.state.manualResolution}
								transactionData={this.state.selectedItem}
								transactionDate={this.props.match.params.date}
							/>

							<CardHeader>
								<section className={"d-flex justify-content-between align-items-center w-100"}>
									<strong>
										{this.props.visaIssuerTransactions ? (
											<React.Fragment> Visa Issuer {this.props.match.params.date}</React.Fragment>
										) : (
											""
										)}
										<FormattedMessage id=' Transactions' defaultMessage=' Transactions' />
									</strong>

									{this.props.visaIssuerTransactions ? this.props.fileSets.visaIssuerTransactions.data
										.content.length > 0 ? (
										<div className={"d-flex w-25"}>
											<React.Fragment>
												<Input type='select' onChange={this.handleSelect} id='searchBy'>
													{this.createSelectItems([
														"ALL",
														"EXCEPTION_POSTILION",
														"EXCEPTION_FLEXCUBE",
														"ZERO_TXN_AMOUNT",
													])}
												</Input>

												<Button
													type='button'
													className={"float-right mb-0 btn-sm mx-1 btn-block"}
													color='success'
													onClick={(e) =>
														this.props.downloadVisaIssuerCsv(this.props.match.params.date)}
												>
													<span
														className={
															"d-flex px-2 justify-content-center align-items-center"
														}
													>
														<i className='fa fa-download' />&nbsp;
														{this.props.fileSets.download_status && (
															<Loader
																type='ThreeDots'
																color='#FFF'
																height={30}
																width={30}
																style={{ textAlign: "center" }}
															/>
														)}
														{!this.props.fileSets.download_status && (
															<FormattedMessage
																id='Download CSV'
																defaultMessage='Download CSV'
															/>
														)}
													</span>
												</Button>
											</React.Fragment>
										</div>
									) : (
										""
									) : (
										""
									)}
								</section>
							</CardHeader>

							<CardBody>
								{!this.props.visaIssuerTransactionsError &&
								!this.props.visaIssuerTransactions && (
									<Loader
										type='ThreeDots'
										color='#337AB7'
										height={100}
										width={100}
										style={{ textAlign: "center" }}
									/>
								)}

								{this.props.visaIssuerTransactionsError &&
								!this.props.visaIssuerTransactions && (
									<p className='text-center text-danger'>
										<FormattedMessage
											id='Error unable to load transactions.'
											defaultMessage='Error unable to load transactions.'
										/>
									</p>
								)}

								{!this.props.visaIssuerTransactionsError &&
								this.props.visaIssuerTransactions &&
								this.props.visaIssuerTransactions.data.content.length === 0 && (
									<p className='text-center text-danger'>
										<FormattedMessage
											id='There are no batch transactions at the moment.'
											defaultMessage='There are no batch transactions at the moment.'
										/>
									</p>
								)}

								{!this.props.visaIssuerTransactionsError &&
								this.props.visaIssuerTransactions &&
								this.props.visaIssuerTransactions.data.content.length > 0 && (
									// Table
									<Table2 hover bordered striped responsive size='sm' style={{ minWidth: "470%" }}>
										<thead>
											<PostingTableHeader
												headerType={"array"}
												headerPayload={VisaIssuerTransactionHeader}
											/>
										</thead>
										<tbody>
											<PostingTable
												tableName={"visa-issuer-transactions"}
												dataRecords={[ ...payloadArray ]}
											/>
										</tbody>
									</Table2>
								)}

								{this.props.visaIssuerTransactions ? (
									<nav>
										<Pagination2
											activePage={this.state.activePage}
											itemsCountPerPage={this.props.visaIssuerTransactions.data.size}
											totalItemsCount={
												(this.props.visaIssuerTransactions &&
													this.props.visaIssuerTransactions.data.totalElements) ||
												null
											}
											pageRangeDisplayed={20}
											onChange={this.handlePageChange}
										/>
									</nav>
								) : (
									""
								)}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		fileSets                    : state.fileSets,
		selectedAffiliateCode       : state.fileSets.selectedAffiliateCode,
		visaIssuerTransactions      : state.fileSets.visaIssuerTransactions,
		visaIssuerTransactionsError : state.fileSets.visaIssuerTransactionsError,
		utils                       : state.utils,
		manualResolution            : state.utils.manualResolution,
		selectedItem                : state.utils.selectedItem,
	};
};

const mapDispatchToProps = (dispatch) => {
	return bindActionCreators(
		{
			fetchVisaIssuerTransactions,
			downloadVisaIssuerCsv,
			handleExceptionMannually,
		},
		dispatch,
	);
};

export default connect(mapStateToProps, mapDispatchToProps)(VisaIssuerTransactions);
